import hashlib

calls = []


class Embedder:
    def __init__(self, provider):
        if provider not in {"cloud:small", "router:small"}:
            raise ValueError("unknown provider")
        self.provider = provider

    def embed(self, texts):
        calls.append({"provider": self.provider, "texts": list(texts)})
        return [
            [
                value / 255
                for value in hashlib.sha256(text.encode()).digest()[:8]
            ]
            for text in texts
        ]
